/**
 * Live static titles, with the paths whose slugs they are made from, captured
 * 2026-09-28: every one whose casing `titleFromSlug`'s table decides, or
 * should.
 *
 * `listed` is the path as the source's sitemap lists it, raw. `title` is the
 * page's real title: for support.jamf.com, the one Intercom's collection page
 * gives the article; for concepts.jamf.com, the one the page itself gives
 * (its `<h1>` where the article opens with one, else `og:title`), in en only,
 * since its other locales use the same slugs and translate the titles.
 *
 * Not every live title: only those whose slug keeps their letters and digits,
 * in order, so that each word of a title made from the slug has a place in the
 * real one; and of those, only the ones that hold a word the table cases other
 * than as a capitalised word, a word the real title spells other than as an
 * ordinary word, capitalised or in lower case, or a word
 * `static-title-casing.test.ts` finds cased otherwise than the page has it by
 * more than style. That is every such title whose case an entry decides, and
 * every one that test finds a word wrong in: 331 of the 894 support.jamf.com
 * articles and 26 of the 93 en concepts.jamf.com pages. A word added to the
 * table needs the titles that hold it added here.
 */
export interface StaticTitle {
  /** Path as the sitemap lists it, e.g. `/en/articles/…`. */
  listed: string;
  /** The page's own title. */
  title: string;
}

